commands.windows:
# Standalone example: is the SaaS monitoring native messaging host registered, per browser.
foreach ($k in 'HKLM:\SOFTWARE\Google\Chrome\NativeMessagingHosts\dev.mustra.saas_monitor', 'HKLM:\SOFTWARE\Microsoft\Edge\NativeMessagingHosts\dev.mustra.saas_monitor') {
  if (Test-Path $k) { "registered: $k" } else { "not registered: $k" }
}
